function getCampo(obj, nombreBuscado) {
  if (!obj) return undefined;
  const key = Object.keys(obj).find(k => k.trim().toLowerCase() === nombreBuscado.toLowerCase());
  return key ? obj[key] : undefined;
}

const facturasActuales = new Set(
  $('JSON deseado').all()
    .filter(item => (getCampo(item.json.output, 'Alianza cliente') ?? '').toString().trim() === 'BoxCargo')
    .map(item => (getCampo(item.json.output, 'factura') ?? '').toString().trim())
);

console.log('Total facturas actuales encontradas:', facturasActuales.size);

const pendientesAirtable = $input.all();

const pagadas = pendientesAirtable.filter(item => {
  const factura = (item.json.fields?.factura ?? item.json.fields?.Factura ?? '').toString().trim();
  return factura && !facturasActuales.has(factura);
});

return pagadas.map(item => ({
  json: {
    id: item.json.id,
    factura: item.json.fields?.factura ?? item.json.fields?.Factura
  }
}));

function getCampo(obj, nombreBuscado) {
  if (!obj) return undefined;
  const key = Object.keys(obj).find(k => k.trim().toLowerCase() === nombreBuscado.toLowerCase());
  return key ? obj[key] : undefined;
}
function tieneValor(v) {
  return v !== undefined && v !== null && v !== '';
}
function esNumeroValido(v) {
  const n = Number(v);
  return tieneValor(v) && !isNaN(n) && n > 0;
}

const camposNoVacios = [
  { key: 'factura', label: 'Factura' },
  { key: 'suite', label: 'Suite' },
  { key: 'alianza', label: 'Alianza' },
  { key: 'Tipo de cliente', label: 'Tipo de cliente' },
  { key: 'nombre', label: 'Nombre' },
  { key: 'fecha emision de factura', label: 'Fecha de emisión' },
  { key: 'Telefono', label: 'Teléfono' }
];

return $input.all().map(item => {
  const data = item.json.fields || {};

  console.log('Campos disponibles:', Object.keys(data));

  const faltantes = [];

  camposNoVacios.forEach(c => {
    if (!tieneValor(getCampo(data, c.key))) faltantes.push(c.label);
  });
  if (!esNumeroValido(getCampo(data, 'Valor Total'))) faltantes.push('Valor Total (debe ser mayor a 0)');
  if (!esNumeroValido(getCampo(data, 'Plazo de pago'))) faltantes.push('Plazo de pago (debe ser mayor a 0)');

  const nombre = getCampo(data, 'nombre');
  const suite = getCampo(data, 'suite');
  const factura = getCampo(data, 'factura');

  const partesId = [];
  if (tieneValor(nombre)) partesId.push(nombre);
  if (tieneValor(suite)) partesId.push(`Suite ${suite}`);
  if (tieneValor(factura)) partesId.push(`Factura ${factura}`);

  item.json['informacion completa'] = faltantes.length === 0;
  item.json.__identificacion = partesId.length ? partesId.join(' — ') : 'Registro sin datos identificadores';
  item.json.__camposFaltantes = faltantes.join(', ');

  return item;
});

const items = $input.all();
if (items.length === 0) return [];

let texto = `🚨 Facturas con datos incompletos — Boxcargo\n${items.length} registro(s) necesitan revisión\n\n`;

items.forEach((item, i) => {
  const d = item.json;
  texto += `${i + 1}. ${d.__identificacion}\nFalta: ${d.__camposFaltantes}\n\n`;
});

texto += `_Por favor revisa y actualiza el Excel de origen._`;

return [{ json: { texto } }];

return $input.all().map(item => {
  const data = item.json.fields || {};

  const estado = data['Estado de Factura'];
  const categoria = data['Categorización de Mora'] || '';
  const diasDeMora = data['Días de Mora'] || 0;
  const ultimaNotificacion = data['Ultima notificación'] || '';
  const nombre = data['nombre'] || 'cliente';
  const factura = data['factura'] || '';
  const valorTotal = data['Valor Total'] || 0;

  let accion = null;
  let mensaje = null;
  let nuevoValorNotificacion = null;

  if (estado !== 'Pagada') {
    if (estado === 'Vencida' && categoria && categoria !== ultimaNotificacion) {
      accion = 'aviso_mora';
      nuevoValorNotificacion = categoria;
      mensaje = `Hola ${nombre}, tu factura ${factura} por valor de $${valorTotal} está vencida hace ${diasDeMora} días (${categoria}). Por favor regulariza tu pago lo antes posible.`;
    } else if (estado === 'Próxima a vencer' && ultimaNotificacion !== 'Aviso Previo') {
      accion = 'aviso_previo';
      nuevoValorNotificacion = 'Aviso Previo';
      mensaje = `Hola ${nombre}, te recordamos que tu factura ${factura} por valor de $${valorTotal} vence mañana. Evita la mora realizando tu pago a tiempo.`;
    }
  }

  item.json.__accionNotificacion = accion;
  item.json.__mensaje = mensaje;
  item.json.__nuevoValorNotificacion = nuevoValorNotificacion;
  return item;
});

const items = $input.all();
if (items.length === 0) return [];

const grupos = {};
for (const item of items) {
  const categoria = item.json.__nuevoValorNotificacion || 'Sin categoría';
  if (!grupos[categoria]) grupos[categoria] = [];
  grupos[categoria].push(item.json);
}

return Object.entries(grupos).map(([categoria, registros]) => {
  let texto = `📢 Solicitud de aprobación — ${categoria}\n${registros.length} persona(s)\n\n`;
  registros.forEach(r => {
    texto += `• ${r.fields?.nombre ?? r.__identificacion} — Factura ${r.fields?.factura ?? ''} — $${r.fields?.['Valor Total'] ?? ''}\n`;
  });

  return {
    json: { categoria, texto, registros }
  };
});
